  "profile.saveInfo":      { es: "Guardar cambios",     en: "Save changes",       pt: "Salvar alterações" },
  "profile.savedOk":       { es: "Perfil actualizado",  en: "Profile updated",    pt: "Perfil atualizado" },
  "profile.changePassword":{ es: "Cambiar contraseña",  en: "Change password",    pt: "Alterar senha" },
  "profile.currentPwd":    { es: "Contraseña actual",   en: "Current password",   pt: "Senha atual" },
  "profile.newPwd":        { es: "Nueva contraseña",    en: "New password",       pt: "Nova senha" },
